import {systemPermissionNames} from './delegation.js';
const permissionNames={review:'พิจารณาใบสมัคร',checkin:'เช็คอิน',reports:'ดูรายงาน',schedule:'จัดการเวลาเปิด–ปิดรับสมัคร'};
export function mountStaffManager(root,client,eventId,parentCurrent,{system=false}={}){
 const names=system?systemPermissionNames:permissionNames,actions=system?{lookup:'lookupDelegate',list:'listDelegates',assign:'assignDelegate'}:{lookup:'lookupStaff',list:'listStaff',assign:'assign'};
 const panel=document.createElement('div');panel.className='panel staff-manager';root.append(panel);const current=()=>parentCurrent()&&panel.isConnected;
 panel.innerHTML='<h3>มอบหมายเจ้าหน้าที่</h3><p class="sub">เจ้าหน้าที่ต้องเข้าสู่ระบบด้วย Google อย่างน้อยหนึ่งครั้งก่อน ใช้อีเมลของบัญชีนั้นเพื่อค้นหา สิทธิ์มีผลเฉพาะกิจกรรมที่เลือก</p><form class="staff-lookup"><label>อีเมลเจ้าหน้าที่<input name="email" type="email" autocomplete="off" maxlength="254" required placeholder="name@example.com"></label><button type="submit">ค้นหาบัญชี</button></form><p role="status" class="staff-status"></p><div class="staff-editor"></div><h3>รายชื่อเจ้าหน้าที่ของกิจกรรมนี้</h3><button type="button" class="staff-refresh">อัปเดตรายชื่อ</button><div class="staff-list"></div><button type="button" class="staff-more" hidden>โหลดรายชื่อเพิ่ม</button>';
 if(system){panel.querySelector('h3').textContent='มอบหมายงานดูแลระบบแทน Admin';panel.querySelector('.sub').textContent='สิทธิ์กลุ่มนี้มีผลกับทุกกิจกรรมและทั้งเว็บไซต์ เจ้าหน้าที่ต้องเข้าด้วย Google อย่างน้อยหนึ่งครั้ง Admin เท่านั้นที่มอบหมายหรือถอนสิทธิ์ได้ ผู้รับสิทธิ์มอบหมายต่อไม่ได้';panel.querySelectorAll('h3')[1].textContent='ผู้ได้รับมอบหมายงานทั้งระบบ';}
 const lookup=panel.querySelector('form'),status=panel.querySelector('[role=status]'),editor=panel.querySelector('.staff-editor'),list=panel.querySelector('.staff-list'),more=panel.querySelector('.staff-more'),refresh=panel.querySelector('.staff-refresh');let next=null,busy=false,revision=0,listRevision=0;
 const tell=text=>{if(current())status.textContent=text};
 function edit(user){editor.replaceChildren();const sections=new Map(),sectionNames={createEvents:'กิจกรรมและการเปิดใช้งาน',editEvents:'กิจกรรมและการเปิดใช้งาน',posters:'กิจกรรมและการเปิดใช้งาน',registrationControl:'กิจกรรมและการเปิดใช้งาน',checkinControl:'กิจกรรมและการเปิดใช้งาน',banners:'ประชาสัมพันธ์หน้าเว็บ',applicationsTrash:'ถังขยะและการลบข้อมูล',eventsTrash:'ถังขยะและการลบข้อมูล',purgeEvents:'ถังขยะและการลบข้อมูล',audit:'การตรวจสอบย้อนหลัง'};const form=document.createElement('form');const identity=document.createElement('p');identity.textContent=user.displayName+' · '+(user.email||'ไม่มีอีเมล')+(user.disabled?' · บัญชีถูกปิดหรือไม่พบ สามารถถอนสิทธิ์ได้':'');form.append(identity);
  for(const [key,title] of Object.entries(names)){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.name=key;if(system&&['purgeEvents','audit'].includes(key))label.className='sensitive-permission';check.checked=!user.disabled&&user.permissions.includes(key);check.disabled=user.disabled===true;label.append(check,document.createTextNode(' '+title));if(system){const sectionName=sectionNames[key];if(!sections.has(sectionName)){const group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=sectionName;group.append(legend);form.append(group);sections.set(sectionName,group)}sections.get(sectionName).append(label)}else form.append(label)}
  const note=document.createElement('p');note.className='sub';note.textContent=system?'นำเครื่องหมายออกทั้งหมดเพื่อถอนงานทั้งระบบ · ไม่เปลี่ยนสิทธิ์เฉพาะกิจกรรม · ลบถาวรจะลบข้อมูลผู้สมัคร รูปภาพ และลายเซ็นของกิจกรรมนั้นด้วย':'นำเครื่องหมายออกทั้งหมดเพื่อถอนสิทธิ์จากกิจกรรมนี้';const save=document.createElement('button');save.type='submit';save.className='primary';save.textContent='บันทึกสิทธิ์';const cancel=document.createElement('button');cancel.type='button';cancel.textContent='ปิด';cancel.onclick=()=>{editor.replaceChildren();revision++};form.append(note,save,cancel);editor.append(form);
  form.onsubmit=event=>{event.preventDefault();if(busy||!current())return;const permissions=Object.keys(names).filter(key=>form.elements[key].checked),modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();const message=document.createElement('p');message.textContent=(system?'ยืนยันมอบหมายงานทั้งระบบ (ทุกกิจกรรม) · ':'')+(permissions.length?'มอบหมาย '+permissions.map(key=>names[key]).join(', '):(system?'ถอนงานทั้งระบบทั้งหมด':'ถอนสิทธิ์ทั้งหมดในกิจกรรมนี้'))+' ให้ '+user.displayName+' ('+(user.email||'ไม่มีอีเมล')+')?';const confirm=document.createElement('button');confirm.className='primary';confirm.textContent='ยืนยัน';body.append(message,confirm);modal.showModal();confirm.onclick=async()=>{if(busy||!current()||!form.isConnected)return;busy=true;save.disabled=confirm.disabled=true;try{await client.operate({action:actions.assign,eventId,targetUid:user.uid,permissions,...(system?{expectedVersion:user.version||0}:{})});if(!current())return;modal.close();editor.replaceChildren();tell('บันทึกสิทธิ์แล้ว');await load(false)}catch(error){if(current())message.textContent=error.message||'บันทึกไม่ได้'}finally{busy=false;save.disabled=confirm.disabled=false}}};
 }
 lookup.elements.email.oninput=()=>{revision++;editor.replaceChildren()};
 lookup.onsubmit=async event=>{event.preventDefault();if(busy)return;const mine=++revision,email=lookup.elements.email.value.trim(),button=lookup.querySelector('button');button.disabled=true;editor.replaceChildren();tell('กำลังค้นหาบัญชี…');try{const user=await client.operate({action:actions.lookup,eventId,email});if(!current()||mine!==revision)return;edit(user);tell('พบบัญชีแล้ว กรุณาตรวจชื่อและอีเมลก่อนมอบหมาย')}catch(error){if(mine===revision)tell(error.message||'ค้นหาไม่ได้')}finally{button.disabled=false}};
 async function load(append=false){const mine=++listRevision;refresh.disabled=more.disabled=true;try{const data=await client.operate({action:actions.list,eventId,...(append?{after:next}:{})});if(!current()||mine!==listRevision)return;if(!append)list.replaceChildren();if(!append&&!data.items.length){const p=document.createElement('p');p.textContent='ยังไม่มีเจ้าหน้าที่ในกิจกรรมนี้';list.append(p)}for(const user of data.items){const row=document.createElement('article');row.className='staff-member';const info=document.createElement('div'),name=document.createElement('strong'),email=document.createElement('p'),rights=document.createElement('p');name.textContent=user.displayName;email.textContent=user.email||'ไม่มีอีเมล';email.className=rights.className='sub';rights.textContent=user.active?user.permissions.map(p=>names[p]||p).join(' · '):'ถอนสิทธิ์แล้ว';info.append(name,email,rights);const button=document.createElement('button');button.textContent='แก้ไขสิทธิ์';button.onclick=()=>{if(busy)return;revision++;edit(user);editor.scrollIntoView({block:'nearest',behavior:'smooth'})};row.append(info,button);list.append(row)}next=data.next;more.hidden=!next}catch(error){if(mine===listRevision)tell(error.message||'โหลดรายชื่อไม่ได้')}finally{if(mine===listRevision)refresh.disabled=more.disabled=false}}
 refresh.onclick=()=>{if(!busy)load(false)};more.onclick=()=>{if(!busy)load(true)};load(false);
}
